CREATE OR REPLACE FUNCTION public.check_discount_dynamic(member_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
BEGIN
    EXECUTE  $dynamic$SELECT 1 WHERE 5 <= (SELECT nullif(COUNT(1),0) FROM bookings 
            WHERE bookings.memid = $1 
            AND starttime >= now()-(INTERVAL '6 month'))$dynamic$ USING member_id ;
    if found then
        return true;
    else
        return false;
    end if;
/*
Query to check output
SELECT 1 WHERE 5 <= (SELECT COUNT(*) FROM bookings 
            WHERE bookings.memid = 1 
            AND starttime >= now()-(INTERVAL '6 month'))
*/

END;
$_$;

