CREATE FUNCTION public.fetchallfacilities(integer) RETURNS SETOF character varying
    LANGUAGE plpgsql
    AS $_$ 
DECLARE
   cur  CURSOR FOR  SELECT name from facilities order by random()  limit $1 ; 
   var_data facilities.name%type;
BEGIN
   OPEN cur ;
   LOOP
      FETCH NEXT FROM cur INTO var_data;
      EXIT WHEN NOT FOUND;
      RETURN NEXT var_data;
   END LOOP;
      RETURN NEXT concat_ws('','Last Facility - ',var_data);
   CLOSE cur;
END
$_$;





CREATE OR REPLACE FUNCTION public.get_facility_booking_summary(p_facid integer)
RETURNS SETOF refcursor
    LANGUAGE plpgsql
    AS $$
    DECLARE
    cur1 refcursor;
    cur2 cur1%type;
BEGIN
    open cur1 for SELECT concat_ws('',firstname,"Surname") as Mem_Name , min(starttime) FirstBooking, max(starttime) LastBooking,
    count(bookid) as "TotalBooking",
    sum(slots) as "TotalSlots"
    FROM bookings inner join members on bookings.memid = members.memid
    WHERE facid = p_facid
    group by members.memid
    order by "TotalBooking" desc;
    RETURN NEXT cur1;
    open cur2 for SELECT name as "FacilityName", membercost,guestcost
	FROM facilities
	WHERE facid = p_facid;
     RETURN NEXT cur2;
END;
$$;



