CREATE OR REPLACE  FUNCTION public.get_member_name(p_memid integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fname TEXT;
    v_lname TEXT;
    v_fullname TEXT;
BEGIN
    SELECT firstname , "Surname"
    INTO v_fname , v_lname
    FROM members
    WHERE memid = p_memid;
    if found then
        v_fullname := concat_ws(' ',v_fname,v_lname);
    end if;
    return v_fullname;
END;
$$;


CREATE OR REPLACE FUNCTION public.getfacilitiescost(facid integer) 
RETURNS TABLE(membercost numeric, guestcost numeric)
    LANGUAGE plpgsql
    AS $$
declare
membercost numeric;
guestcost numeric;
begin 
select monthlymaintenance, membercost , guestcost  into  membercost, guestcost
from facilities f where facid = facid;

return query select membercost, guestcost;
end ;
$$;


CREATE OR REPLACE FUNCTION public.search_bookings(text, text)
RETURNS TABLE(totalbooking bigint, member_name text, facility_name character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    sql_query TEXT;
BEGIN
    sql_query := format(
        'SELECT count(b.bookid) "TotalBooking", m.firstname || '' '' || m."Surname" AS member_name, f.name AS facility_name
         FROM bookings b
         JOIN members m ON b.memid = m.memid
         JOIN facilities f ON b.facid = f.facid
         WHERE (m.%s ilike ''%s'')
         group by m.firstname, m."Surname", f.name',$1, $2);
    RETURN QUERY EXECUTE sql_query;
END;
$_$;

