CREATE VIEW public.booking_details AS
 SELECT count(b.bookid) AS "BookingCount",
    f.name AS facility_name,
    (((m.firstname)::text || ' '::text) || (m."Surname")::text) AS member_name,
    sum(b.slots) AS "TotalSlots"
   FROM ((public.bookings b
     JOIN public.facilities f ON ((b.facid = f.facid)))
     JOIN public.members m ON ((b.memid = m.memid)))
  GROUP BY f.name, (((m.firstname)::text || ' '::text) || (m."Surname")::text);


