CREATE OR REPLACE FUNCTION prevent_overlapping_bookings()
RETURNS TRIGGER AS $$
BEGIN

    IF  EXISTS (
        SELECT 1
        FROM bookings
        WHERE facid = NEW.facid
        AND NEW.starttime < (starttime + (slots * interval '30 minutes'))
        AND (NEW.starttime + (NEW.slots * interval '30 minutes')) > starttime
    ) THEN
     
        RAISE exception using message ='Booking overlaps with an existing booking', ERRCODE ='A0001' ;
    END IF;
    RETURN NEW;
    /*
            -- Find the first available time after the requested start time
       SELECT to_char(starttime + (slots * interval '30 minutes'),'DD-MON-YYYY HH24:MI')
        INTO next_available
        FROM bookings
        WHERE facid = NEW.facid
        AND starttime >= NEW.starttime
        ORDER BY starttime + (slots * interval '30 minutes')
        LIMIT 1;
    */
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER check_no_overlapping_booking
BEFORE INSERT OR UPDATE ON bookings
FOR EACH ROW
EXECUTE FUNCTION prevent_overlapping_bookings();

CREATE OR REPLACE PROCEDURE createbooking(
    facid integer,
    memid integer,
    starttime  timestamp without time zone,
    slots integer
)
LANGUAGE plpgsql
AS $$

BEGIN
    VALUES (facid, memid, to_char(starttime,'DD-MON-YYYY HH24:MI')::timestamp without time zone, slots);
    commit;
    exception 
    when others then
    rollback;
    raise exception using message = 'Booking Failed!';

END;
$$;

ANALYZE;

